const element = (tag, text) => {
  const node = document.createElement(tag);
  node.textContent = text;
  return node;
};
for (const [id, [name, description, formula, scope, url]] of Object.entries(ppiMethods)) {
  const article = element('article', '');
  article.id = id;
  const source = element('a', '方法參考 ↗');
  source.href = url;
  source.target = '_blank';
  source.rel = 'noopener';
  article.append(element('h3', name), element('p', description), element('pre', formula),
    element('h4', '適用範圍'), element('p', scope), source);
  document.getElementById(hubs.has(id) ? 'hubs' : 'communities').append(article);
